/**
 * Oqto OpenUI profile runtime. Pure data + @openuidev/lang-core: no React.
 * Artefacts in schema/ are generated by tools/sync-upstream.ts from the pinned
 * upstream OpenUI library plus Oqto's @Answer action and rules.
 */
import { createParser, createStreamingParser } from "@openuidev/lang-core";
import catalogJson from "../schema/catalog.json" with { type: "json" };
import libraryJson from "../schema/library.json" with { type: "json" };
import profileJson from "../schema/profile.json" with { type: "json" };
export { PROFILE_ID } from "./constants.js";
export const PROFILE_VERSION = profileJson.version;
export const ROOT = profileJson.root;
export const librarySchema = libraryJson;
export const catalog = catalogJson;
export const componentNames = Object.keys(catalogJson.components);
import { SYSTEM_PROMPT } from "./generated/prompt.js";
/** The model instructions. Inject only when OpenUI is enabled for the Session. */
export function systemPrompt() {
    return SYSTEM_PROMPT;
}
export const createOqtoParser = () => createParser(librarySchema, ROOT);
export const createOqtoStreamingParser = () => createStreamingParser(librarySchema, ROOT);
